package r02;

public class ForTest02 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int i=1; i<=5; i++) {
		System.out.println(i + ".ㅇㅇㅇ");
		
		}
		
		System.out.println();
		
		
		int i2 = 1;
		while( i2 <= 5 ) {
			System.out.println(i2 + ".ㅇㅇㅇ");
			i2++;
		}
		
		int i3 = 1;
		do {
			System.out.println(i3 + ".ㅇㅇㅇ");
			i3++;
			
		}while(i3 <= 5);
		
		
	}
}


